CREATE TYPE "RequirementStatus" AS ENUM('DRAFT','ACTIVE','CANCELLED','EXPIRED'); CREATE TYPE "ContactMethod" AS ENUM('IN_APP','PHONE','WHATSAPP','EMAIL');
CREATE TYPE "LeadStatus" AS ENUM('NEW','VIEWED','RESPONDED','CONTACT_SHARED','IN_DISCUSSION','CLOSED','NOT_INTERESTED','INVALID','SPAM','EXPIRED'); CREATE TYPE "InvalidReportStatus" AS ENUM('OPEN','APPROVED','REJECTED'); CREATE TYPE "CreditLedgerReason" AS ENUM('LEAD_RESPONSE','REFUND','ADMIN_GRANT','ADJUSTMENT');
CREATE TABLE customer_requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,event_type varchar(80) NOT NULL,city_id uuid NOT NULL REFERENCES locations(id) ON DELETE RESTRICT,locality_id uuid REFERENCES locations(id) ON DELETE RESTRICT,event_date date NOT NULL,alternate_date date,category_id uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT,guest_count integer,budget_min decimal(12,2),budget_max decimal(12,2),required_services text[] NOT NULL DEFAULT '{}',style_tradition varchar(120),description varchar(4000) NOT NULL,preferred_contact "ContactMethod" NOT NULL DEFAULT 'IN_APP',intent_verified boolean NOT NULL DEFAULT true,status "RequirementStatus" NOT NULL DEFAULT 'ACTIVE',expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(guest_count IS NULL OR guest_count>0),CHECK(budget_min IS NULL OR budget_min>=0),CHECK(budget_max IS NULL OR budget_max>=budget_min));
CREATE INDEX customer_requirements_customer_status_created_idx ON customer_requirements(customer_id,status,created_at); CREATE INDEX customer_requirements_match_idx ON customer_requirements(city_id,category_id,event_date,status);
CREATE TABLE lead_recipients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requirement_id uuid NOT NULL REFERENCES customer_requirements(id) ON DELETE CASCADE,business_id uuid NOT NULL REFERENCES vendor_businesses(id) ON DELETE CASCADE,status "LeadStatus" NOT NULL DEFAULT 'NEW',preview_viewed_at timestamptz,responded_at timestamptz,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(requirement_id,business_id)); CREATE INDEX lead_recipients_business_status_created_idx ON lead_recipients(business_id,status,created_at);
CREATE TABLE lead_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES lead_recipients(id) ON DELETE CASCADE,author_user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,message varchar(2000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX lead_responses_recipient_created_idx ON lead_responses(recipient_id,created_at);
CREATE TABLE lead_contact_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requirement_id uuid NOT NULL REFERENCES customer_requirements(id) ON DELETE RESTRICT,recipient_id uuid NOT NULL REFERENCES lead_recipients(id) ON DELETE RESTRICT,customer_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,consent_version varchar(40) NOT NULL,consent_text text NOT NULL,consent_hash varchar(64) NOT NULL,shared_fields text[] NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(requirement_id,recipient_id));
CREATE TABLE vendor_credit_accounts(business_id uuid PRIMARY KEY REFERENCES vendor_businesses(id) ON DELETE CASCADE,balance integer NOT NULL DEFAULT 0 CHECK(balance>=0),updated_at timestamptz NOT NULL DEFAULT now()); INSERT INTO vendor_credit_accounts(business_id) SELECT id FROM vendor_businesses ON CONFLICT DO NOTHING;
CREATE TABLE vendor_credit_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid NOT NULL REFERENCES vendor_credit_accounts(business_id) ON DELETE RESTRICT,recipient_id uuid REFERENCES lead_recipients(id) ON DELETE RESTRICT,amount integer NOT NULL CHECK(amount<>0),balance_after integer NOT NULL CHECK(balance_after>=0),reason "CreditLedgerReason" NOT NULL,reference varchar(160),created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX vendor_credit_ledger_business_created_idx ON vendor_credit_ledger(business_id,created_at);
CREATE TABLE lead_invalid_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_id uuid NOT NULL REFERENCES lead_recipients(id) ON DELETE RESTRICT,reason varchar(1000) NOT NULL,status "InvalidReportStatus" NOT NULL DEFAULT 'OPEN',resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX lead_invalid_reports_status_created_idx ON lead_invalid_reports(status,created_at);
CREATE TABLE notification_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requirement_id uuid REFERENCES customer_requirements(id) ON DELETE CASCADE,recipient_user_id uuid NOT NULL,template varchar(80) NOT NULL,payload jsonb NOT NULL DEFAULT '{}',sent_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX notification_outbox_sent_created_idx ON notification_outbox(sent_at,created_at);
CREATE FUNCTION prevent_immutable_lead_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'record is immutable'; END $$;
CREATE TRIGGER vendor_credit_ledger_immutable BEFORE UPDATE OR DELETE ON vendor_credit_ledger FOR EACH ROW EXECUTE FUNCTION prevent_immutable_lead_change(); CREATE TRIGGER lead_contact_grants_immutable BEFORE UPDATE OR DELETE ON lead_contact_grants FOR EACH ROW EXECUTE FUNCTION prevent_immutable_lead_change();
ALTER TABLE customer_requirements ENABLE ROW LEVEL SECURITY; ALTER TABLE lead_recipients ENABLE ROW LEVEL SECURITY; ALTER TABLE lead_responses ENABLE ROW LEVEL SECURITY; ALTER TABLE lead_contact_grants ENABLE ROW LEVEL SECURITY; ALTER TABLE vendor_credit_accounts ENABLE ROW LEVEL SECURITY; ALTER TABLE vendor_credit_ledger ENABLE ROW LEVEL SECURITY; ALTER TABLE lead_invalid_reports ENABLE ROW LEVEL SECURITY; ALTER TABLE notification_outbox ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON customer_requirements,lead_recipients,lead_responses,lead_contact_grants,vendor_credit_accounts,vendor_credit_ledger,lead_invalid_reports,notification_outbox FROM anon,authenticated;
INSERT INTO permissions(code,description) VALUES('lead.manage','Review invalid and spam lead reports'),('credits.manage','Grant and refund vendor lead credits') ON CONFLICT(code) DO NOTHING; INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code IN('MODERATOR','SUPER_ADMIN') AND p.code IN('lead.manage','credits.manage') ON CONFLICT DO NOTHING;
